// Parity guard for the pre-rendered .section-context nav (post-#129 audit,
// extended sitewide after the audit found the same JS-insertion CLS bug on
// every other page matching a context in v1-editorial-interior-v4.js --
// see docs/FINAL-CLOSURE-AUDIT-2026-08-27.md and
// scripts/build-section-context-nav.py).
//
// Every page generated by that builder hand-copies (well, script-copies)
// buildContextNav()'s output into static HTML so it paints on first frame
// instead of being inserted by JS after load (the CLS fix). That is a
// second, generated copy of what the JS would produce at runtime -- exactly
// the kind of duplication that drifts silently if the two definitions
// (Python CONTEXTS vs JS contexts) diverge. This test derives the
// JS-generated version fresh for every such page (by stripping the
// pre-rendered <nav> and letting v1-editorial-interior-v4.js build it from
// scratch, same as any page without one) and diffs it against the committed
// markup link-by-link. The page list is discovered from git-tracked HTML,
// not hardcoded, so a page the builder newly covers is checked automatically.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import http from 'node:http';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { chromium } from 'playwright';

const ROOT = process.cwd();

function discoverPages() {
  const tracked = execFileSync('git', ['ls-files', '-z', '*.html'], { cwd: ROOT, encoding: 'utf8' })
    .split('\0').filter(Boolean);
  return tracked.filter((rel) => {
    if (rel.startsWith('lab/')) return false;
    const text = fs.readFileSync(path.join(ROOT, rel), 'utf8');
    return /<nav class="section-context"/.test(text);
  }).sort();
}

const PAGES = discoverPages();
assert.ok(PAGES.length > 0, 'no pre-rendered .section-context pages found to check');

const MIME = new Map([
  ['.html', 'text/html; charset=utf-8'], ['.css', 'text/css; charset=utf-8'],
  ['.js', 'text/javascript; charset=utf-8'], ['.mjs', 'text/javascript; charset=utf-8'],
  ['.json', 'application/json; charset=utf-8'], ['.webp', 'image/webp'], ['.png', 'image/png'],
  ['.jpg', 'image/jpeg'], ['.jpeg', 'image/jpeg'], ['.svg', 'image/svg+xml'], ['.woff2', 'font/woff2'],
  ['.ico', 'image/x-icon'],
]);

const NAV_RE = /<nav class="section-context"[\s\S]*?<\/nav>\s*/;

function extractLinks(html) {
  const linksBlockMatch = html.match(/<div class="section-context__links">([\s\S]*?)<\/div>/);
  assert.ok(linksBlockMatch, 'no .section-context__links block found');
  const anchors = [...linksBlockMatch[1].matchAll(/<a href="([^"]+)"(\s+aria-current="page")?>([^<]+)<\/a>/g)];
  assert.ok(anchors.length > 0, 'no <a> links parsed from .section-context__links');
  return anchors.map(m => ({ href: m[1], current: !!m[2], label: m[3] }));
}

// Serving a renamed temp file (e.g. fragmento/__parity-check.html) would
// change location.pathname -- harmless for the prefix-matched contexts the
// original 5-page fix batch happened to cover, but it silently breaks any
// exact-match context (e.g. 'samuel' matches path === '/fragmento/' exactly,
// not a prefix) because the renamed URL no longer equals that exact string,
// so buildContextNav() correctly finds no context and the test would fail
// for a page that isn't actually broken. Instead, serve the ORIGINAL url
// unchanged and swap in stripped content in-memory via a query flag, so
// location.pathname in the browser is byte-identical to the real page.
const strippedByPath = new Map();

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://127.0.0.1');
  const clean = decodeURIComponent(url.pathname).replace(/^\/+/, '');
  const wantsStripped = url.searchParams.has('parityStripped');
  if (wantsStripped && strippedByPath.has(url.pathname)) {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
    res.end(strippedByPath.get(url.pathname));
    return;
  }
  let file = clean === '' ? 'index.html' : clean;
  let full = path.join(ROOT, file);
  if (fs.existsSync(full) && fs.statSync(full).isDirectory()) full = path.join(full, 'index.html');
  if (!fs.existsSync(full) || !fs.statSync(full).isFile()) {
    res.writeHead(404); res.end('not found'); return;
  }
  const type = MIME.get(path.extname(full).toLowerCase()) || 'application/octet-stream';
  res.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'no-store' });
  res.end(fs.readFileSync(full));
});
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
const ORIGIN = `http://127.0.0.1:${server.address().port}`;

function urlPathFor(rel) {
  const withoutIndex = rel.replace(/(^|\/)index\.html$/, '$1');
  return '/' + (withoutIndex === '' ? '' : withoutIndex);
}

const browser = await chromium.launch({ headless: true, ...(process.env.QA_CHROMIUM_EXECUTABLE_PATH ? { executablePath: process.env.QA_CHROMIUM_EXECUTABLE_PATH } : {}) });

for (const rel of PAGES) {
  const original = fs.readFileSync(path.join(ROOT, rel), 'utf8');
  const committedNavMatch = original.match(NAV_RE);
  assert.ok(committedNavMatch, `${rel}: no pre-rendered <nav class="section-context"> found`);
  const committedLinks = extractLinks(committedNavMatch[0]);

  // Strip the pre-rendered nav so the page looks like one that never had
  // it -- exactly the condition buildContextNav()'s own guard checks for.
  const stripped = original.replace(NAV_RE, '');
  const urlPath = urlPathFor(rel);
  strippedByPath.set(urlPath, stripped);

  try {
    const page = await browser.newPage();
    await page.goto(`${ORIGIN}${urlPath}?parityStripped=1`, { waitUntil: 'networkidle' });
    const generatedOuter = await page.locator('.section-context').first().evaluate(el => el.outerHTML).catch(() => null);
    assert.ok(generatedOuter, `${rel}: v1-editorial-interior-v4.js did not generate a .section-context when none was pre-rendered`);
    const generatedLinks = extractLinks(generatedOuter);

    assert.deepEqual(
      generatedLinks, committedLinks,
      `${rel}: pre-rendered .section-context__links drifted from what buildContextNav() generates.\n` +
      `committed: ${JSON.stringify(committedLinks)}\ngenerated: ${JSON.stringify(generatedLinks)}`
    );
    await page.close();
  } finally {
    strippedByPath.delete(urlPath);
  }
}

await browser.close();
server.close();
console.log(`PASS section-context parity (${PAGES.length} pre-rendered pages match buildContextNav() output)`);
